from functools import lru_cache

def countNoZeroPairs(n: int) -> int:
    # Digits of n from least significant to most significant.
    digits = []
    x = n
    while x > 0:
        digits.append(x % 10)
        x //= 10
    L = len(digits)

    # dp(i, carry, a_done, b_done): count ways to fill positions i..L-1 so that
    # a + b = n, where a_done/b_done indicate the number has already ended
    # (no more digits at this position or higher). All placed digits are 1..9.
    @lru_cache(maxsize=None)
    def dp(i, carry, a_done, b_done):
        if i == L:
            # All digits consumed; valid only if nothing is carried out.
            return 1 if carry == 0 else 0
        d = digits[i]
        total = 0
        # Possible contributions of a at this position: (value, ends_here).
        if a_done:
            a_choices = [(0, True)]
        else:
            a_choices = [(da, False) for da in range(1, 10)]
            if i >= 1:
                a_choices.append((0, True))   # a ends here (already has >=1 digit)
        if b_done:
            b_choices = [(0, True)]
        else:
            b_choices = [(db, False) for db in range(1, 10)]
            if i >= 1:
                b_choices.append((0, True))
        for a_val, a_end in a_choices:
            for b_val, b_end in b_choices:
                s = a_val + b_val + carry
                if s % 10 == d:
                    total += dp(i + 1, s // 10, a_end, b_end)
        return total

    return dp(0, 0, False, False)
